function newsletterSignup(strEmail,arrMoreFields){$('#listSignupLoading').fadeIn(250);jQuery.ajax({url:'/wp-admin/admin-ajax.php',dataType:'json',data:({action:'ajaxAddToMailingList',EMAIL:strEmail,FNAME:arrMoreFields.Fname,LNAME:arrMoreFields.Lname,ENEWSLETTE:arrMoreFields.Newsletter,BULLION:arrMoreFields.Bullion,US:arrMoreFields.USnum,WORLD:arrMoreFields.WORLDnum,CONSIGN:arrMoreFields.Selling}),success:function(objData,strStatus,jqXHR){if(objData.success==true){if($('#emailpreferences').length&&$('#email_address').length&&strEmail.toLowerCase()===$('#email_address').val().toLowerCase()){window.location.reload();return;}
$('#listpopup .signupform, #listpopup .button').css('display','none');$('#listpopup .thankyou').css('display','block');}else{$('#listpopup .submiterror').html('<strong>We are sorry, an unexpected error occurred!</strong><br /> '+objData.message);$('#listpopup .submiterror').css('display','block');};$('#listSignupLoading').fadeOut(250);}});}
function listSignup(){var blnError=false;var objOptions={chkNewsletter:'No',chkBullion:'No',chkUSnum:'No',chkWORLDnum:'No',chkSelling:'No'};var strEmail=$('#listSignupEmail').val();var strFname=$('#listSignupFname').val();var strLname=$('#listSignupLname').val();$.each(objOptions,function(key,value){if($('#'+key).is(":checked")==true){objOptions[key]='Yes';};});if(strEmail==''){blnError=true;$('#listSignupError_email').css('display','block');$('#listSignupEmail').addClass('error');}else{blnError=false;$('#listSignupError_email').css('display','none');$('#listSignupEmail').removeClass('error');};var arrAddInfo={Email:strEmail,Fname:strFname,Lname:strLname,Newsletter:objOptions.chkNewsletter,Bullion:objOptions.chkBullion,USnum:objOptions.chkUSnum,WORLDnum:objOptions.chkWORLDnum,Selling:objOptions.chkSelling};if(blnError==false){newsletterSignup(strEmail,arrAddInfo);};};var popupProductflag=false;function popupProduct(target){if(document.getElementsByClassName("popup_title show")[0]!=undefined)
document.getElementsByClassName("popup_title show")[0].classList.remove("show");target.children[1].classList.toggle("show");popupProductflag=true;}
function removePopup(){if(document.getElementsByClassName("popup_title show")[0]!=undefined&&popupProductflag==false)
document.getElementsByClassName("popup_title show")[0].classList.remove("show");popupProductflag=false;}